-- The MIRA Adoption Map: the processes of science, the personas in it, their use cases, the tools
-- that serve them, and the value of adopting MIRA. Generated by create_supabase.py from schema.json
-- (in the adoption repository); change those rather than this file.
--
-- Use cases are the extensions page's public.use_cases, so the page and the map share one list:
-- the map adds its columns there, and the use cases it brings show on the page like any other.
-- Members are the library's public.members; the map adds their profiles.
--
-- Who can do what:
-- - Anyone can read the map, except leads (members only). Use cases are read through
--   public.use_case_map, which leaves hidden ones out, as the extensions page's views do.
-- - Members can add, change and remove rows of the map, add use cases, and change the map's columns of
--   any use case. A use case's title, goal, gap, field and author stay as the extensions page has them:
--   only its edit key or an admin changes them, through edit_use_case.
-- - A member's change to a use case's texts (narrative, practices, benefit) makes a new version, kept
--   like the page's own versions; changing how a use case is classified or linked does not.
-- - Members read every profile and change their own.

-- Helpers -------------------------------------------------------------------------------------------

-- The member the signed-in account stands for: a second (alias) account counts as its member.
create function private.current_member_id() returns uuid
  language sql stable security definer set search_path = ''
as $$
  select coalesce(m.alias_of, m.user_id) from public.members m where m.user_id = (select auth.uid());
$$;

-- Keeps who made a row and when; moves updated_at.
create function private.adoption_before_update() returns trigger
  language plpgsql set search_path = ''
as $$
begin
  new.created_by := old.created_by;
  new.created_at := old.created_at;
  new.updated_at := now();
  return new;
end;
$$;

revoke execute on function private.current_member_id(), private.adoption_before_update()
  from public, anon, authenticated;
grant execute on function private.current_member_id() to authenticated;

-- Tables --------------------------------------------------------------------------------------------

create table public.processes (
  id uuid primary key default gen_random_uuid(),
  name text not null unique check (btrim(name) <> '' and char_length(name) <= 200),
  also_known_as text check (char_length(also_known_as) <= 200),
  kind text check (kind in ('Activity', 'Dataflow')),
  description text check (char_length(description) <= 5000),
  parent_process_id uuid references public.processes (id) on delete set null,
  flows_from_id uuid references public.processes (id) on delete set null,
  flows_to_id uuid references public.processes (id) on delete set null,
  traditional_form text check (char_length(traditional_form) <= 5000),
  mira_form text check (char_length(mira_form) <= 5000),
  status text check (status in ('As-is', 'Transformed by MIRA', 'New with MIRA')),
  entry_point_how text check (char_length(entry_point_how) <= 5000),
  diffusion_point_how text check (char_length(diffusion_point_how) <= 5000),
  prior_art_stage text[] not null default '{}' check (prior_art_stage <@ array['Plan', 'Collect', 'Process', 'Analyse', 'Preserve', 'Share', 'Reuse', 'Organise & Document', 'Store', 'Protect', 'Publish', 'Discover', 'Authoring', 'Peer review', 'Discovery & Dissemination']),
  tldraw_ref text check (char_length(tldraw_ref) <= 200),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid default auth.uid() references auth.users (id) on delete set null
);
comment on table public.processes is 'Subprocesses of the scientific process: blocks (activities) and arrows (dataflows) of the tldraw process map, both as-is and as MIRA would transform them.';
comment on column public.processes.also_known_as is 'Other names different groups use for this process, comma-separated. Keep Name as the canonical one.';
comment on column public.processes.kind is 'Activity = a block on the map; Dataflow = an arrow between two processes.';
comment on column public.processes.parent_process_id is 'The enclosing process, if this is a subprocess.';
create index on public.processes (parent_process_id);
comment on column public.processes.flows_from_id is 'Dataflows only: the source process.';
create index on public.processes (flows_from_id);
comment on column public.processes.flows_to_id is 'Dataflows only: the target process.';
create index on public.processes (flows_to_id);
comment on column public.processes.traditional_form is 'How this happens today, without MIRA (e.g. peer review).';
comment on column public.processes.mira_form is 'How this happens with MIRA (e.g. comment in the MIRA commons).';
comment on column public.processes.prior_art_stage is 'Matching stage(s) in published research lifecycles (RDMkit, CESSDA, ACRL).';
comment on column public.processes.tldraw_ref is 'Shape ID or deep link in the tldraw map.';
create trigger adoption_before_update before update on public.processes for each row execute function private.adoption_before_update();

create table public.personas (
  id uuid primary key default gen_random_uuid(),
  name text not null unique check (btrim(name) <> '' and char_length(name) <= 200),
  description text check (char_length(description) <= 5000),
  category text check (category in ('Producer', 'Consumer', 'Curator', 'Evaluator', 'Funder', 'Infrastructure')),
  flywheel_role text[] not null default '{}' check (flywheel_role <@ array['Input', 'Evaluation', 'Consumption']),
  goals_incentives text check (char_length(goals_incentives) <= 5000),
  pain_points text check (char_length(pain_points) <= 5000),
  network_reach text check (network_reach in ('Low', 'Medium', 'High')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid default auth.uid() references auth.users (id) on delete set null
);
comment on table public.personas is 'Actors in the scientific process.';
comment on column public.personas.flywheel_role is 'Role in the minimal adoption loop (Input / Evaluation / Consumption users).';
comment on column public.personas.network_reach is 'How many other personas they influence.';
create trigger adoption_before_update before update on public.personas for each row execute function private.adoption_before_update();

create table public.adoption_values (
  id uuid primary key default gen_random_uuid(),
  name text not null unique check (btrim(name) <> '' and char_length(name) <= 200),
  type text check (type in ('Enriches commons', 'Institutional adoption', 'Mandate', 'Incentive', 'Funding', 'Teaching/onboarding', 'Socialization', 'Feedback/iteration', 'Virality', 'Tool diversity', 'Reputation/authority')),
  sign text check (sign in ('+', '−')),
  description text check (char_length(description) <= 5000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid default auth.uid() references auth.users (id) on delete set null
);
comment on table public.adoption_values is 'Value to MIRA when a persona adopts it: how adoption spreads, feeds the commons, or backfires.';
comment on column public.adoption_values.sign is '+ helps MIRA; − is a risk.';
create trigger adoption_before_update before update on public.adoption_values for each row execute function private.adoption_before_update();

create table public.tools (
  id uuid primary key default gen_random_uuid(),
  name text not null unique check (btrim(name) <> '' and char_length(name) <= 200),
  description text check (char_length(description) <= 5000),
  variant_of_id uuid references public.tools (id) on delete set null,
  organization text check (char_length(organization) <= 200),
  url text check (char_length(url) <= 500 and url ~ '^https://[^[:space:]]+$'),
  repository text check (char_length(repository) <= 500 and repository ~ '^https://[^[:space:]]+$'),
  maturity text check (maturity in ('Wanted', 'Idea', 'Prototype', 'In use', 'Production')),
  scope text[] not null default '{}' check (scope <@ array['Local', 'Global']),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid default auth.uid() references auth.users (id) on delete set null
);
comment on table public.tools is 'Existing and wanted tools. A missing tool is a row with Maturity = Wanted.';
comment on column public.tools.variant_of_id is 'Tool family, e.g. the different extractors.';
create index on public.tools (variant_of_id);
comment on column public.tools.scope is 'Local = enables MIRA thinking internally; Global = puts local thinking in a global context.';
create trigger adoption_before_update before update on public.tools for each row execute function private.adoption_before_update();

create table public.coverage (
  id uuid primary key default gen_random_uuid(),
  tool_id uuid references public.tools (id) on delete set null,
  use_case_id uuid references public.use_cases (id) on delete set null,
  support text check (support in ('Supports now', 'Partial', 'Planned', 'Could easily')),
  helps_role text[] not null default '{}' check (helps_role <@ array['Author', 'Consumer', 'Sponsor', 'Feedback between them']),
  notes text check (char_length(notes) <= 5000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid default auth.uid() references auth.users (id) on delete set null
);
comment on table public.coverage is 'Which tool supports which process or use case, and for whom. The HOW of a tool is the use case it implements: link that use case (add it if missing) rather than describing it here.';
create index on public.coverage (tool_id);
comment on column public.coverage.use_case_id is 'The use case the tool implements, i.e. its mechanism (e.g. Semble: "Curate a collection of links").';
create index on public.coverage (use_case_id);
create trigger adoption_before_update before update on public.coverage for each row execute function private.adoption_before_update();

create table public.leads (
  id uuid primary key default gen_random_uuid(),
  organization text not null unique check (btrim(organization) <> '' and char_length(organization) <= 200),
  stage text check (stage in ('Idea', 'Contacted', 'Interested', 'Pilot')),
  notes text check (char_length(notes) <= 5000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid default auth.uid() references auth.users (id) on delete set null
);
comment on table public.leads is 'Potential partners and pilots.';
create trigger adoption_before_update before update on public.leads for each row execute function private.adoption_before_update();

-- Use cases: the map's columns on the extensions page's table ---------------------------------------

-- The map's use cases have no goal or gap of their own; the page's forms still require both.
alter table public.use_cases alter column goal drop not null, alter column gap drop not null;
alter table public.use_cases add column level text check (level in ('Goal', 'Use case', 'Step'));
comment on column public.use_cases.level is 'Goal = an end in itself (the why); Use case = something a persona does (the what; vote at this level); Step = a part of a journey, rarely meaningful alone.';
alter table public.use_cases add column composition_type text check (composition_type in ('Sequence', 'Aspects', 'Means'));
comment on column public.use_cases.composition_type is 'How the children relate to this row. Sequence = ordered steps of a journey (do them in order). Aspects = facets (you need ALL of them). Means = alternative ways to reach this goal (ANY ONE will do; different tools often sit on different means).';
alter table public.use_cases add column horizon text check (horizon in ('Currently possible', 'Aspirational'));
alter table public.use_cases add column novelty text check (novelty in ('New with MIRA', 'Classical, transformed', 'Classical, improved'));
alter table public.use_cases add column narrative text check (char_length(narrative) <= 5000);
alter table public.use_cases add column current_practice text check (char_length(current_practice) <= 5000);
alter table public.use_cases add column mira_practice text check (char_length(mira_practice) <= 5000);
alter table public.use_cases add column benefit_to_persona text check (char_length(benefit_to_persona) <= 5000);
alter table public.use_cases add column virality_point boolean not null default false;
comment on column public.use_cases.virality_point is 'Doing this exposes MIRA to new people.';
alter table public.use_cases add column source text check (char_length(source) <= 200);
comment on column public.use_cases.source is 'Where this row came from (e.g. the Google Doc section).';

-- Member profiles -------------------------------------------------------------------------------------

create table public.member_profiles (
  user_id uuid primary key references public.members (user_id) on delete cascade,
  organization text check (char_length(organization) <= 200),
  bio text check (char_length(bio) <= 5000),
  orcid text check (char_length(orcid) <= 500 and orcid ~ '^https://[^[:space:]]+$'),
  updated_at timestamptz not null default now()
);
comment on table public.member_profiles is 'What members say about themselves, shown to other members.';
comment on column public.member_profiles.bio is 'A few lines on who you are and what you work on, shown to other members.';
comment on column public.member_profiles.orcid is 'https://orcid.org/…';

