-- Use case versions -----------------------------------------------------------------------------------
-- A use case's version holds what a visitor sees of it; the map's texts are part of that from now on.
-- (Versions kept before this migration simply lack them.)

create or replace function private.extensions_page_use_case_fields(p_id uuid)
  returns jsonb
  language sql stable set search_path = ''
as $$
  select jsonb_build_object('title', u.title, 'goal', u.goal, 'gap', u.gap, 'field', u.field,
                            'author_name', u.author_name, 'narrative', u.narrative, 'current_practice', u.current_practice, 'mira_practice', u.mira_practice, 'benefit_to_persona', u.benefit_to_persona)
    from public.use_cases u
   where u.id = p_id;
$$;

-- The extensions page's functions make their own versions. A member's direct change of these texts
-- makes one too: the version number moves before the change is written, and the version is kept
-- after. Changes made inside the page's functions (which run as their owner) are left to them.
create function private.use_cases_member_version() returns trigger
  language plpgsql set search_path = ''
as $$
begin
  if current_user = 'authenticated' and (new.narrative is distinct from old.narrative or new.current_practice is distinct from old.current_practice or new.mira_practice is distinct from old.mira_practice or new.benefit_to_persona is distinct from old.benefit_to_persona) then
    new.version_no := old.version_no + 1;
    new.updated_at := now();
  end if;
  return new;
end;
$$;

create function private.keep_member_use_case_version(p_id uuid, p_no integer, p_full boolean)
  returns void
  language plpgsql volatile security definer set search_path = ''
as $$
begin
  if not coalesce(private.is_member(), false) then
    raise exception 'Only members can change the map.';
  end if;
  perform private.extensions_page_keep_version(null, p_id, p_no, p_full);
end;
$$;

create function private.use_cases_keep_member_version() returns trigger
  language plpgsql set search_path = ''
as $$
begin
  if current_user = 'authenticated'
     and (tg_op = 'INSERT' or new.version_no is distinct from old.version_no) then
    perform private.keep_member_use_case_version(new.id, new.version_no, tg_op = 'INSERT');
  end if;
  return null;
end;
$$;

revoke execute on function private.use_cases_member_version(), private.keep_member_use_case_version,
  private.use_cases_keep_member_version() from public, anon, authenticated;
grant execute on function private.keep_member_use_case_version to authenticated;

create trigger use_cases_member_version before update on public.use_cases
  for each row execute function private.use_cases_member_version();
create trigger use_cases_keep_member_version after insert or update on public.use_cases
  for each row execute function private.use_cases_keep_member_version();

-- What visitors read -------------------------------------------------------------------------------
-- use_case_map reads with its owner's rights (security_invoker off), like the extensions page's views,
-- so that it can leave out hidden use cases while visitors have no rights on use_cases. Links name the
-- rows they point to by id; Composed of keeps its order. tools_now counts the tools that support the use
-- case now, and gap says that none does.

create view public.use_case_map with (security_invoker = false, security_barrier = true) as
select
  u.id, u.title, u.level, u.composition_type, u.horizon, u.novelty, u.narrative, u.current_practice, u.mira_practice, u.benefit_to_persona, u.virality_point, u.source,
  coalesce((select jsonb_agg(j.persona_id order by j.persona_id) from public.use_case_primary_persona j
             where j.use_case_id = u.id), '[]'::jsonb) as primary_persona,
  coalesce((select jsonb_agg(j.persona_id order by j.persona_id) from public.use_case_counterpart_personas j
             where j.use_case_id = u.id), '[]'::jsonb) as counterpart_personas,
  coalesce((select jsonb_agg(j.persona_id order by j.persona_id) from public.use_case_also_used_by j
             where j.use_case_id = u.id), '[]'::jsonb) as also_used_by,
  coalesce((select jsonb_agg(j.composed_of_id order by j.position, j.composed_of_id) from public.use_case_composed_of j
             where j.use_case_id = u.id), '[]'::jsonb) as composed_of,
  coalesce((select jsonb_agg(j.process_id order by j.process_id) from public.use_case_processes j
             where j.use_case_id = u.id), '[]'::jsonb) as processes,
  coalesce((select jsonb_agg(j.depends_on_id order by j.depends_on_id) from public.use_case_depends_on j
             where j.use_case_id = u.id), '[]'::jsonb) as depends_on,
  (select count(*) from public.coverage c
    where c.use_case_id = u.id and c.support = 'Supports now')::integer as tools_now,
  not exists (select 1 from public.coverage c
               where c.use_case_id = u.id and c.support = 'Supports now') as gap
from public.use_cases u
where not u.hidden;

-- The same for processes; the tables it reads are readable by anyone, so it reads with the visitor's rights.
create view public.process_status with (security_invoker = true) as
select p.id, p.name,
       count(c.id)::integer as tools_now,
       count(c.id) = 0 as gap
  from public.processes p
  left join public.coverage_process cp on cp.process_id = p.id
  left join public.coverage c on c.id = cp.coverage_id and c.support = 'Supports now'
 group by p.id;

-- Access ------------------------------------------------------------------------------------------

alter table public.processes enable row level security;
revoke all on public.processes from public, anon, authenticated;
grant select, insert, update, delete on public.processes to authenticated;
grant select on public.processes to anon;
create policy "Anyone can read" on public.processes for select to anon, authenticated using (true);
create policy "Members can add" on public.processes for insert to authenticated with check ((select private.is_member()));
create policy "Members can change" on public.processes for update to authenticated using ((select private.is_member())) with check ((select private.is_member()));
create policy "Members can remove" on public.processes for delete to authenticated using ((select private.is_member()));

