-- Use cases: members read them (admins also the hidden ones), add them, and change the map's columns.
-- Everything else stays as the extensions page set it: no grants to signed-out visitors, and the
-- title, goal, gap, field, author, hiding and version only through the page's functions.
grant select on public.use_cases to authenticated;
grant insert (title, goal, gap, field, author_name, level, composition_type, horizon, novelty, narrative, current_practice, mira_practice, benefit_to_persona, virality_point, source) on public.use_cases to authenticated;
grant update (level, composition_type, horizon, novelty, narrative, current_practice, mira_practice, benefit_to_persona, virality_point, source) on public.use_cases to authenticated;
create policy "Members can read" on public.use_cases for select to authenticated
  using ((select private.is_member()) and (not hidden or (select private.is_library_admin())));
create policy "Members can add" on public.use_cases for insert to authenticated with check ((select private.is_member()));
create policy "Members can change the map" on public.use_cases for update to authenticated
  using ((select private.is_member()) and (not hidden or (select private.is_library_admin()))) with check ((select private.is_member()));

-- Profiles: members read them all and write their own.
alter table public.member_profiles enable row level security;
revoke all on public.member_profiles from public, anon, authenticated;
grant select, insert, update, delete on public.member_profiles to authenticated;
create policy "Members can read profiles" on public.member_profiles for select to authenticated using ((select private.is_member()));
create policy "Members write their own profile" on public.member_profiles for insert to authenticated
  with check ((select private.is_member()) and user_id = (select private.current_member_id()));
create policy "Members change their own profile" on public.member_profiles for update to authenticated
  using (user_id = (select private.current_member_id())) with check (user_id = (select private.current_member_id()));
create policy "Members remove their own profile" on public.member_profiles for delete to authenticated
  using (user_id = (select private.current_member_id()));

